import re
from typing import List, Union

def evaluate(expr: str) -> float:
    Token = Union[str, float]

    # Tokenizer: numbers, operators, parentheses
    token_re = re.compile(r'\s*(\d+(?:\.\d+)?|[-+*/()])')
    tokens: List[Token] = []
    pos = 0
    n = len(expr)
    while pos < n:
        m = token_re.match(expr, pos)
        if not m:
            # leftover non-whitespace that didn't match
            if expr[pos:].strip() == '':
                break
            raise ValueError("invalid character")
        tok = m.group(1)
        if tok[0].isdigit() or (tok[0] == '.' and len(tok) > 1 and tok[1].isdigit()):
            tokens.append(float(tok))
        else:
            tokens.append(tok)
        pos = m.end()

    if not tokens:
        raise ValueError("empty expression")

    idx = 0

    def peek() -> Token:
        return tokens[idx] if idx < len(tokens) else None

    def parse_primary() -> float:
        nonlocal idx
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end")
        if tok == '-':
            idx += 1
            return -parse_primary()
        if tok == '+':
            idx += 1
            return parse_primary()
        if tok == '(':
            idx += 1
            val = parse_expr()
            if peek() != ')':
                raise ValueError("missing )")
            idx += 1
            return val
        if isinstance(tok, float):
            idx += 1
            return tok
        raise ValueError("expected number or (")

    def parse_term() -> float:
        nonlocal idx
        val = parse_primary()
        while peek() in ('*', '/'):
            op = peek()
            idx += 1
            rhs = parse_primary()
            if op == '*':
                val *= rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val /= rhs
        return val

    def parse_expr() -> float:
        nonlocal idx
        val = parse_term()
        while peek() in ('+', '-'):
            op = peek()
            idx += 1
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    result = parse_expr()
    if idx != len(tokens):
        raise ValueError("extra tokens")
    return float(result)

