from collections import deque

class RateLimiter:
    def __init__(self, max_calls: int, period: float):
        self.max_calls = max_calls
        self.period = period
        self._allowed_times = deque()

    def allow(self, t: float) -> bool:
        cutoff = t - self.period
        while self._allowed_times and self._allowed_times[0] <= cutoff:
            self._allowed_times.popleft()

        if len(self._allowed_times) < self.max_calls:
            self._allowed_times.append(t)
            return True
        return False

